from entities import Container, ContainerTypefrom services.container import ContainerServicefrom sqlalchemy.ext.asyncio import AsyncSessionfrom schemas.channel import  CreatePublic, CreatePrivatefrom utils.post import generate_slugclass ChannelService(ContainerService):    async def get_channel(self, channel_id: int) -> Container:        return await self.get_by_or_raise(            id=channel_id,            type=[                ContainerType.PUBLIC_CHANNEL,                ContainerType.PRIVATE_CHANEL            ]        )class PublicChannelService(ContainerService):    async def create_public_channel(self, create: CreatePublic, user_id: int):        await self.check_already_exists(            slug=create.slug, type=ContainerType.PUBLIC_CHANNEL        )        create.slug = generate_slug(create.slug)        return await self.create_item(            author_id=user_id, **create.dict(),            type=ContainerType.PUBLIC_CHANNEL        )    async def get_channel(self, channel_id: int) -> Container:        return await self.get_by_or_raise(            id=channel_id,            type=ContainerType.PUBLIC_CHANNEL        )class PrivateChannelService(ContainerService):    async def create_private_channel(self, create: CreatePrivate, user_id: int):        return await self.create_item(            author_id=user_id, **create.dict(),            type=ContainerType.PRIVATE_CHANEL        )    async def get_channel(self, channel_id: int) -> Container:        return await self.get_by_or_raise(            id=channel_id,            type=ContainerType.PRIVATE_CHANEL        )